import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { Browser, CHROME, until } from './chrome';

const target = 'packages/dom/src/style/numeric.ts';
const ambiguous = ['animation'];

if (!await Bun.file(CHROME).exists()) {
  console.log(`No Chrome at ${CHROME} - set CHROME to regenerate ${target}.`);
  process.exit(1);
}

function probe() {
  const style = document.createElement('div').style as unknown as Record<string, string>;
  const keys = new Set<string>();
  const valid = (key: string, value: unknown) => {
    style[key] = '';
    style[key] = value as string;
    return style[key] !== '';
  };

  for (let proto = style; proto; proto = Object.getPrototypeOf(proto))
    for (const key of Object.getOwnPropertyNames(proto))
      if (/^[a-z][a-zA-Z]*$/.test(key) && typeof style[key] == 'string' && key != 'cssText')
        keys.add(key);

  return [...keys].filter((key) =>
    valid(key, 1) || ['1px', '1px 1px', '1px 1px 1px', '1px serif'].some((value) => valid(key, value))
  ).sort();
}

const server = Bun.serve({
  port: 0,
  fetch: () =>
    new Response(
      `<!doctype html><html><body><pre id="out"></pre><script>` +
      `document.getElementById('out').textContent = JSON.stringify((${probe})());` +
      `</script></body></html>`,
      { headers: { 'content-type': 'text/html' } }
    )
});

const profile = mkdtempSync(join(tmpdir(), 'numeric-properties-'));
const browser = new Browser();
let out: string | null = null;

try {
  await browser.open(`http://localhost:${server.port}/`, profile);
  out = await until(() => browser.text('#out'), 10000);
} finally {
  await browser.close();
  server.stop(true);
  rmSync(profile, { recursive: true, force: true });
}

const names = (JSON.parse(out!) as string[]).filter((name) => !ambiguous.includes(name));

writeFileSync(target, [
  `/** Properties where a number is valid CSS - generated by .github/scripts/numeric-properties.ts. */`,
  `type Numeric =`,
  ...names.map((name) => `  | '${name}'`),
  `;`,
  ``,
  `export type { Numeric };`,
  ``
].join('\n').replace(/\n;/, ';'));

console.log(`Wrote ${names.length} properties to ${target}.`);
